// Version of this page: ONE number, MAJOR.MINOR.PATCH (the pill shows it, the update check compares it with version.json). PATCH counts the commits since the last push, MINOR counts the pushes to the live site since the last major (a push: 19.0.4 -> 19.1.0), MAJOR is raised only when the owner says so (19.3.2 -> 20.0.0). Every commit: raise it and write the same value into version.json ({"version":"MAJOR.MINOR.PATCH"}).
const APP_VERSION='23.11.4';
// Debug mode (admin only): shows details for debugging (the SH ratio, the full / taken / squad bonus damage of a strike ...); everyone else sees the result only. The admin switches it in the account panel; the choice is kept in this browser (DBGWANT) and counts only while the account is an admin (DEV)
let DEV=false,DBGWANT=false;try{DBGWANT=localStorage.getItem('krappy_debug')=='1'}catch(e){}
// ---- Traffic statistics (GoatCounter: no cookies, no personal data, no consent notice needed). OFF until GC_CODE holds the code of your GoatCounter site (the part before .goatcounter.com).
// It runs only on the real site (not in a preview) and never for an admin account. A visit is counted by GoatCounter itself; on top of that every VISIT reports once which view, attack mode, epic and language it used (events "view/...", "mode/...", "epic/...", "lang/...").
// Nothing you type, no export text and no account data is ever sent.
const GC_CODE='krappy';
const gcOn=()=>!!GC_CODE&&location.hostname=='hracik.github.io';
(function(){if(!gcOn())return;const s=document.createElement('script');s.async=true;s.dataset.goatcounter='https://'+GC_CODE+'.goatcounter.com/count';s.src='https://gc.zgo.at/count.js';document.head.appendChild(s)})();
const GCSEEN=new Set();
function track(path){
  if(!gcOn()||GCSEEN.has(path)||(typeof SY!=='undefined'&&SY.role=='admin'))return;GCSEEN.add(path);
  const go=()=>{try{window.goatcounter.count({path,title:path,event:true})}catch(e){}};
  if(window.goatcounter&&window.goatcounter.count)go();else setTimeout(go,3000);
}
function trackUse(P){
  if(!gcOn())return;
  track('lang/'+(document.documentElement.lang||'en'));track('view/'+ATK);track('mode/'+$('mode').value);
  if(ATK=='epics'){const e=$('epic');if(e&&e.value)track('epic/'+e.value)}
}
function syncDebug(){const on=!!(DBGWANT&&typeof SY!=='undefined'&&SY.role=='admin');if(on===DEV)return false;DEV=on;document.documentElement.classList.toggle('dev',on);return true}
// 1-on-1 help (paid service, the menu button 1-on-1 help; the button is hidden since 12.3: delete the word hidden in <button class="nvb hlp" hidden ...> to show it): the hourly rate and the booking link are set here. HELP_URL empty = no Book button, the window says that booking opens soon.
const HELP_RATE='\u20ac25 / hour',HELP_URL='';
(function(){
  const setBadge=(t,st)=>{const b=document.getElementById('appver');if(b){b.textContent=t;b.dataset.s=st||'ok'}};
  const me='v'+APP_VERSION;
  setBadge(me,'unk');
  // Stale-page check: the live site publishes version.json. If it names a NEWER version than this page, the page is reloaded - once per live version, so a browser that keeps serving the old copy cannot loop. A page that is newer than the live site (a test copy) never reloads.
  if(!/^https?:$/.test(location.protocol)){setBadge(me,'unk');return}
  const LIVE='https://hracik.github.io/tb-stack-calculator/';
  const base=/\.github\.io$/.test(location.hostname)?location.origin+location.pathname.replace(/[^\/]*$/,''):LIVE;      // the languages have their own folders (/de/ ...): version.json is always the one in the root
  const tried=()=>{let t=null;try{t=sessionStorage.getItem('sc_reload')}catch(e){}return t||(/^sc_reload=/.test(window.name)?window.name.slice(10):null)};
  const mark=n=>{try{sessionStorage.setItem('sc_reload',n)}catch(e){}window.name='sc_reload='+n};
  const vnum=x=>{const m=/^(\d+)\.(\d+)(?:\.(\d+))?$/.exec(String(x));return m?+m[1]*1e8+ +m[2]*1e4+ +(m[3]||0):0};      // 19.1.2 -> 1901000 + 2: the major counts first, then the minor, then the patch (a two-number version counts as .0)
  let last=0;
  const check=()=>{
    const now=Date.now();if(now-last<300000)return;last=now;
    fetch(base+'version.json?_='+now,{cache:'no-store'}).then(r=>r.ok?r.json():null).then(j=>{
      const ll=String((j&&(j.label||j.version))||''),live=vnum(ll);      // an old version.json also has a label (MAJOR.MINOR): it is read too
      if(!live){setBadge(me,'unk');return}
      if(live<vnum(APP_VERSION)){setBadge(me,'ahead');return}
      if(live==vnum(APP_VERSION)){setBadge(me,'ok');return}
      if(String(tried())===ll){setBadge(me+' \u00b7 live v'+ll,'old');return}
      mark(ll);setBadge(me+' \u00b7 updating','upd');
      try{if(typeof save=='function')save()}catch(e){}      // the numbers typed so far are stored first, the reload then brings them back
      fetch(location.href.split('#')[0],{cache:'reload'}).catch(()=>{}).then(()=>location.reload());
    }).catch(()=>{});
  };
  check();
  document.addEventListener('visibilitychange',()=>{if(!document.hidden)check()});
})();
const $=id=>document.getElementById(id),v=id=>parseFloat(String($(id).value).replace(/,/g,''))||0;
// The number boxes (Leadership, Dominance, Authority, Food prod., the bonuses) show thousands separators: 1875508 -> 1,875,508. Only digits and one decimal point are kept; v() reads the box without the commas.
const NUMBOX='input[inputmode=decimal]';
function fmtInt(s){s=String(s).replace(/[^\d.]/g,'');const i=s.indexOf('.');let a=i<0?s:s.slice(0,i);const b=i<0?'':'.'+s.slice(i+1).replace(/\./g,'');a=a.replace(/^0+(?=\d)/,'');return a.replace(/\B(?=(\d{3})+(?!\d))/g,',')+b}
function fmtBox(el){const old=el.value,pos=el.selectionStart==null?old.length:el.selectionStart,sig=old.slice(0,pos).replace(/[^\d.]/g,'').length,nv=fmtInt(old);if(nv===old)return;el.value=nv;let n=0,i=0;for(;i<nv.length&&n<sig;i++)if(nv[i]!==',')n++;try{el.setSelectionRange(i,i)}catch(x){}}      // formats while typing and keeps the cursor next to the same digit
const fmtAll=()=>document.querySelectorAll(NUMBOX).forEach(el=>{el.value=fmtInt(el.value)});
