      const sy0=y0+yy/f,sy1=y0+(yy+1)/f,sx0=x0+xx/f,sx1=x0+(xx+1)/f;let sum=0,n=0;
      for(let sy=Math.floor(sy0);sy<Math.min(y1,Math.ceil(sy1));sy++)for(let sx=Math.floor(sx0);sx<Math.min(x1,Math.ceil(sx1));sx++){sum+=gr[sy*bw+sx];n++}
